package org.apache.commons.lang;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ClassUtils.getShortClassName
 */
public class ClassUtils_getShortClassName_TriageGen1Test {

    private static final String PACKAGE_SEPARATOR_CHAR = ".";
    private static final String INNER_CLASS_SEPARATOR_CHAR = "$";

    @Test
    public void testGetShortClassName_NullInput() {
        String result = ClassUtils.getShortClassName(null);
        assertEquals(StringUtils.EMPTY, result);
    }

    @Test
    public void testGetShortClassName_EmptyInput() {
        String result = ClassUtils.getShortClassName("");
        assertEquals(StringUtils.EMPTY, result);
    }

    @Test
    public void testGetShortClassName_SimpleClassName() {
        // No dots, no inner class separators
        String className = "java.lang.String";
        String expected = "String";
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_NoPackage() {
        // No dots present
        String className = "MyClass";
        String expected = "MyClass";
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_WithInnerClass() {
        // Contains inner class separator '$'
        // Logic: find last dot, then find '$' after that dot. 
        // If '$' exists, replace '$' with '.'
        String className = "java.util.Scanner$AlphabeticalComparator";
        String expected = "Scanner.AlphabeticalComparator";
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_DeeplyNestedInnerClass() {
        // Test multiple separators
        String className = "com.example.Outer$Inner$DeepInner";
        String expected = "Outer.Inner.DeepInner";
        // Note: The current implementation uses .replace(INNER, PACKAGE), 
        // which replaces all occurrences of '$' in the substring.
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_InnerClassWithoutPackage() {
        // Case where there is no package (no dot), but there is an inner class separator
        // lastDotIdx will be -1. innerIdx will look from 0.
        String className = "Outer$Inner";
        String expected = "Outer.Inner";
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_DotInInnerClassPartButNoInnerClassSeparator() {
        // Case where there is a dot but no '$'
        String className = "org.apache.commons.lang.ClassUtils";
        String expected = "ClassUtils";
        assertEquals(expected, ClassUtils.getShortClassName(className));
    }

    @Test
    public void testGetShortClassName_ComplexScenario() {
        // Mixed dots and dollar signs
        String className = "a.b.C$D.E"; 
        // lastDotIdx is at 'D.E' -> index of dot before E
        // substring is "E"
        // innerIdx search starts after last dot.
        // This tests the boundary of the substring logic.
        String result = ClassUtils.getShortClassName("com.package.Class$Inner");
        assertEquals("Class.Inner", result);
    }
}
